class Solution:
    def maxProduct(self, s: str) -> int:
        n = len(s)
        end = [1] * n
        start = [1] * n
        for c in range(n):
            r = 0
            while c - r - 1 >= 0 and c + r + 1 < n and s[c - r - 1] == s[c + r + 1]:
                r += 1
            if r:
                end[c + r] = max(end[c + r], 2 * r + 1)
                start[c - r] = max(start[c - r], 2 * r + 1)
        for i in range(n - 2, -1, -1):
            end[i] = max(end[i], end[i + 1] - 2)
        for i in range(1, n):
            start[i] = max(start[i], start[i - 1] - 2)
        pre = [0] * n
        suf = [0] * n
        pre[0] = end[0]
        suf[-1] = start[-1]
        for i in range(1, n):
            pre[i] = max(pre[i - 1], end[i])
            suf[n - 1 - i] = max(suf[n - i], start[n - 1 - i])
        return max(pre[i] * suf[i + 1] for i in range(n - 1))

